<?php
if (!defined('ABSPATH')) exit;

/**
 * RC51 — IPPanel-backed mobile ownership verification.
 * OTP values are generated by QuranYar, sent through an approved IPPanel
 * pattern, and stored only as keyed hashes in short-lived transients.
 */
final class QYS_Mobile_OTP {
    private const SENDER_OPTION='qys_ippanel_sender';
    private const PATTERN_OPTION='qys_ippanel_pattern_code';
    private const PARAM_OPTION='qys_ippanel_pattern_param';
    private const OTP_TTL=300;
    private const VERIFIED_TTL=900;
    private const RESEND_SECONDS=60;
    private const MAX_ATTEMPTS=5;
    private const USER_HOURLY_MAX=5;
    private const MOBILE_HOURLY_MAX=3;

    private static function h(string $value): string { return hash_hmac('sha256',$value,wp_salt('nonce').'|qys-mobile-otp'); }
    private static function key(string $type,string $eitaa_id,string $mobile=''): string { return 'qys_otp_'.$type.'_'.substr(self::h($eitaa_id.'|'.$mobile),0,48); }
    private static function otp_hash(string $code,string $eitaa_id,string $mobile): string { return hash_hmac('sha256',$code.'|'.$eitaa_id.'|'.$mobile,wp_salt('auth').'|qys-otp-code'); }

    public static function settings(): array {
        $sender=trim((string)get_option(self::SENDER_OPTION,''));
        $pattern=trim((string)get_option(self::PATTERN_OPTION,''));
        $param=trim((string)get_option(self::PARAM_OPTION,'code'));
        if($param==='')$param='code';
        return ['sender'=>$sender,'pattern_code'=>$pattern,'param'=>$param];
    }

    public static function configured(): bool {
        $s=self::settings();
        return QYS_Token_Store::secret('ippanel')!==''
            && preg_match('/^\+?[0-9]{5,20}$/D',$s['sender'])===1
            && preg_match('/^[A-Za-z0-9_-]{3,190}$/D',$s['pattern_code'])===1
            && preg_match('/^[A-Za-z0-9_]{1,64}$/D',$s['param'])===1;
    }

    public static function contract(): array {
        $s=self::settings();
        return [
            'ready'=>true,
            'provider'=>'ippanel',
            'channel'=>'pattern_sms',
            'code'=>'six_digit',
            'ttl_seconds'=>self::OTP_TTL,
            'attempts'=>self::MAX_ATTEMPTS,
            'registration'=>'required',
            'mobile_change'=>'required',
            'legacy'=>'grandfathered_until_change',
            'configured'=>self::configured(),
            'sender'=>$s['sender']!==''?'configured':'missing',
            'pattern'=>$s['pattern_code']!==''?'configured':'missing',
        ];
    }

    public static function save_admin_settings(string $action): string {
        if(!QYS_Security_Service::is_global_admin())return 'دسترسی کافی برای تنظیم IPPanel وجود ندارد.';
        if($action==='clear_ippanel_token'){
            QYS_Token_Store::clear('ippanel');
            return 'کلید API آی‌پی‌پنل از پیشخوان حذف شد. تنظیمات شماره و الگو حفظ شدند.';
        }
        if($action!=='save_otp_settings')return 'عملیات نامعتبر است.';

        $sender=trim(QYS_Text_Normalizer::digits((string)wp_unslash($_POST['qys_ippanel_sender']??'')));
        $pattern=trim((string)wp_unslash($_POST['qys_ippanel_pattern_code']??''));
        $param=trim((string)wp_unslash($_POST['qys_ippanel_pattern_param']??'code'));
        $token=trim((string)wp_unslash($_POST['qys_ippanel_token']??''));
        if(!preg_match('/^\+?[0-9]{5,20}$/D',$sender))return 'شماره ارسال‌کننده IPPanel معتبر نیست.';
        if(!preg_match('/^[A-Za-z0-9_-]{3,190}$/D',$pattern))return 'کد الگوی IPPanel معتبر نیست.';
        if(!preg_match('/^[A-Za-z0-9_]{1,64}$/D',$param))return 'نام متغیر کد OTP معتبر نیست.';
        if($token!=='' && !QYS_Token_Store::valid($token))return 'فرمت کلید API IPPanel معتبر نیست.';
        if($token!=='' && !QYS_Token_Store::save('ippanel',$token))return 'ذخیره امن کلید API IPPanel انجام نشد.';
        update_option(self::SENDER_OPTION,$sender,false);
        update_option(self::PATTERN_OPTION,$pattern,false);
        update_option(self::PARAM_OPTION,$param,false);
        return self::configured()?'تنظیمات OTP آی‌پی‌پنل ذخیره شد و آماده استفاده است.':'تنظیمات ذخیره شد؛ برای فعال‌شدن OTP کلید API را نیز وارد کنید.';
    }

    private static function recipient(string $mobile): string { return '+98'.substr($mobile,1); }

    private static function hourly_allowed(string $eitaa_id,string $mobile){
        foreach([
            [self::key('uh',$eitaa_id,''),self::USER_HOURLY_MAX],
            [self::key('mh','mobile',$mobile),self::MOBILE_HOURLY_MAX],
        ] as [$key,$max]){
            $state=get_transient($key);$count=is_array($state)?(int)($state['count']??0):0;
            if($count >= $max)return false;
        }
        return true;
    }

    private static function hourly_increment(string $eitaa_id,string $mobile): void {
        foreach([
            [self::key('uh',$eitaa_id,''),self::USER_HOURLY_MAX],
            [self::key('mh','mobile',$mobile),self::MOBILE_HOURLY_MAX],
        ] as [$key,$max]){
            $state=get_transient($key);$count=is_array($state)?(int)($state['count']??0):0;
            set_transient($key,['count'=>min($max,$count+1)],HOUR_IN_SECONDS);
        }
    }

    private static function send_pattern(string $mobile,string $code): array {
        $api=QYS_Token_Store::secret('ippanel');$s=self::settings();
        $payload=[
            'sending_type'=>'pattern',
            'from_number'=>$s['sender'],
            'code'=>$s['pattern_code'],
            'recipients'=>[self::recipient($mobile)],
            'params'=>[$s['param']=>$code],
        ];
        $response=wp_remote_post(QYS_Config::ippanel_send_endpoint(),[
            'timeout'=>12,'redirection'=>0,'reject_unsafe_urls'=>true,'limit_response_size'=>65536,
            'headers'=>['Authorization'=>$api,'Content-Type'=>'application/json','Accept'=>'application/json'],
            'body'=>wp_json_encode($payload),
        ]);
        if(is_wp_error($response))return ['ok'=>false,'uncertain'=>true,'code'=>'network_uncertain'];
        $http=(int)wp_remote_retrieve_response_code($response);
        $body=json_decode(wp_remote_retrieve_body($response),true);
        $accepted=$http>=200&&$http<300&&is_array($body)&&(!empty($body['meta']['status'])||!empty($body['data']['message_outbox_ids']));
        if($accepted)return ['ok'=>true,'uncertain'=>false,'code'=>'accepted'];
        return ['ok'=>false,'uncertain'=>false,'code'=>$http===429?'rate_limited':'provider_rejected'];
    }

    public static function rest_send(WP_REST_Request $req){
        $user=QYS_Security_Service::request_user($req);if(is_wp_error($user))return $user;
        if(!self::configured())return new WP_Error('otp_provider_not_configured','سامانه تأیید پیامکی هنوز توسط مدیر تنظیم نشده است.',['status'=>503]);
        $eitaa_id=(string)$user['id'];$mobile=QYS_Text_Normalizer::mobile((string)$req->get_param('mobile'));
        if($mobile==='')return new WP_Error('mobile','شماره موبایل ایران را به صورت ۰۹xxxxxxxxx وارد کنید.',['status'=>400]);
        if(QYS_Member_Repository::exists_other_mobile($mobile,$eitaa_id))return new WP_Error('duplicate_mobile','این شماره موبایل برای پرونده دیگری ثبت شده است.',['status'=>409]);
        $cooldown=self::key('cd',$eitaa_id,$mobile);
        if(get_transient($cooldown)!==false)return new WP_Error('otp_cooldown','برای ارسال دوباره کد کمی صبر کنید.',['status'=>429,'retry_after'=>self::RESEND_SECONDS]);
        if(!self::hourly_allowed($eitaa_id,$mobile))return new WP_Error('otp_rate_limited','تعداد درخواست کد برای این بازه بیش از حد مجاز است؛ بعداً دوباره تلاش کنید.',['status'=>429]);
        try{$code=(string)random_int(100000,999999);}catch(Throwable $e){return new WP_Error('otp_random','ساخت کد امن ممکن نشد؛ دوباره تلاش کنید.',['status'=>500]);}
        $now=time();$challenge=['hash'=>self::otp_hash($code,$eitaa_id,$mobile),'expires'=>$now+self::OTP_TTL,'attempts'=>0,'mobile'=>$mobile];
        $challenge_key=self::key('ch',$eitaa_id,$mobile);
        set_transient($challenge_key,$challenge,self::OTP_TTL);
        set_transient($cooldown,1,self::RESEND_SECONDS);
        self::hourly_increment($eitaa_id,$mobile);
        $sent=self::send_pattern($mobile,$code);unset($code);
        if(!$sent['ok'] && empty($sent['uncertain'])){
            delete_transient($challenge_key);
            $status=$sent['code']==='rate_limited'?429:502;
            return new WP_Error('otp_send_failed',$sent['code']==='rate_limited'?'درگاه پیامک موقتاً محدود شده است؛ کمی بعد دوباره تلاش کنید.':'ارسال کد تأیید انجام نشد؛ تنظیمات IPPanel یا اعتبار حساب را بررسی کنید.',['status'=>$status]);
        }
        return rest_ensure_response([
            'ok'=>true,'delivery'=>$sent['ok']?'accepted':'uncertain',
            'expires_in'=>self::OTP_TTL,'resend_after'=>self::RESEND_SECONDS,
            'message'=>$sent['ok']?'کد تأیید ۶ رقمی ارسال شد.':'نتیجه ارسال از شبکه قطعی نیست؛ اگر کد رسید آن را وارد کنید، در غیر این صورت پس از یک دقیقه دوباره تلاش کنید.',
        ]);
    }

    public static function rest_verify(WP_REST_Request $req){
        $user=QYS_Security_Service::request_user($req);if(is_wp_error($user))return $user;
        $eitaa_id=(string)$user['id'];$mobile=QYS_Text_Normalizer::mobile((string)$req->get_param('mobile'));
        $code=QYS_Text_Normalizer::digits((string)$req->get_param('otp'));
        if($mobile===''||!preg_match('/^[0-9]{6}$/D',$code))return new WP_Error('otp_invalid','شماره موبایل و کد ۶ رقمی را درست وارد کنید.',['status'=>400]);
        $key=self::key('ch',$eitaa_id,$mobile);$challenge=get_transient($key);
        if(!is_array($challenge)||(int)($challenge['expires']??0)<time()){
            delete_transient($key);return new WP_Error('otp_expired','کد تأیید منقضی شده است؛ کد جدید دریافت کنید.',['status'=>410]);
        }
        $attempts=(int)($challenge['attempts']??0);
        if($attempts>=self::MAX_ATTEMPTS){delete_transient($key);return new WP_Error('otp_locked','تعداد تلاش‌های ناموفق بیش از حد مجاز است؛ کد جدید بگیرید.',['status'=>429]);}
        $expected=(string)($challenge['hash']??'');$actual=self::otp_hash($code,$eitaa_id,$mobile);
        if($expected===''||!hash_equals($expected,$actual)){
            $challenge['attempts']=$attempts+1;$ttl=max(1,(int)$challenge['expires']-time());set_transient($key,$challenge,$ttl);
            return new WP_Error('otp_mismatch','کد تأیید نادرست است.',['status'=>400,'attempts_left'=>max(0,self::MAX_ATTEMPTS-$challenge['attempts'])]);
        }
        delete_transient($key);set_transient(self::key('ok',$eitaa_id,$mobile),['mobile'=>$mobile,'at'=>gmdate('Y-m-d H:i:s')],self::VERIFIED_TTL);
        $member=QYS_Member_Repository::find_by_eitaa_id($eitaa_id);
        if($member && (string)$member->mobile===$mobile)QYS_Member_Repository::mark_mobile_verified((int)$member->id,$mobile);
        return rest_ensure_response(['ok'=>true,'mobile'=>$mobile,'message'=>'مالکیت شماره موبایل تأیید شد. اکنون می‌توانید پرونده را ذخیره کنید.']);
    }

    public static function has_verified_claim(string $eitaa_id,string $mobile): bool {
        $state=get_transient(self::key('ok',$eitaa_id,$mobile));
        return is_array($state)&&hash_equals((string)($state['mobile']??''),$mobile);
    }
    public static function consume_verified_claim(string $eitaa_id,string $mobile): void { delete_transient(self::key('ok',$eitaa_id,$mobile)); }
}
